// ---- bundled from src/ by scripts/build-workflows.js — edit src/, not this ----
const lib = { "executor": (function () {
  const __mods = {
  "executor.js": [function (module, exports, require) {
'use strict';
// Outbox item → Microsoft Graph request(s), and Graph response → outbox report.
// Sarah's mailbox is the only mailbox this module ever sends from. Mail always
// uses the app-only credential. Calendar calls for an employee on delegated
// calendars (item.calendar_auth, resolved at claim time) go to the portal's
// broker instead, which makes the same Graph call with that employee's token
// and passes Graph's status and body back unchanged.
const { DateTime } = require('./luxon');
const { HOLD_CATEGORY } = require('./slots');

const enc = encodeURIComponent;

function recips(list) {
  return (list || []).map((p) => ({ emailAddress: { address: p.address, name: p.name || p.address } }));
}

function utcLocal(iso) {
  return DateTime.fromISO(iso, { setZone: true }).toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss");
}

function mailbox(item) {
  return `${item.config.graph_base_url}/users/${enc(item.config.sarah_upn)}`;
}

function calendarOwner(item) {
  return `${item.config.graph_base_url}/users/${enc(item.payload.employee_upn)}`;
}

const CALENDAR_KINDS = new Set(['create_hold', 'delete_hold', 'create_booking']);

function viaBroker(item, req) {
  if (!CALENDAR_KINDS.has(item.kind) || item.calendar_auth !== 'delegated') return req;
  const url = `${String(item.config.portal_internal_url || '').replace(/\/+$/, '')}/internal/v1/calendar`;
  const who = { employee_upn: item.payload.employee_upn };
  const body = req.method === 'DELETE'
    ? { ...who, op: 'delete_event', event_id: item.payload.event_id }
    : { ...who, op: 'create_event', event: req.body };
  return { method: 'POST', url, body, broker: true };
}

/**
 * First request for a claimed item, or null when no Graph call is needed
 * (booking waiting for approval in shadow mode).
 */
function firstRequest(item) {
  const req = graphRequest(item);
  return req ? viaBroker(item, req) : req;
}

function graphRequest(item) {
  const p = item.payload || {};
  const step = item.step;
  if (step === 'await_approval') return null;

  // A draft already exists (earlier attempt created it, or it was approved): just send it.
  if (step === 'send_draft' || ((item.kind === 'reply' || item.kind === 'new_mail' || item.kind === 'notify_internal')
      && item.draft_graph_id && step === 'full')) {
    return { method: 'POST', url: `${mailbox(item)}/messages/${enc(item.draft_graph_id)}/send`, body: null, sends: true };
  }

  switch (item.kind) {
    case 'reply':
      return {
        method: 'POST',
        url: `${mailbox(item)}/messages/${enc(p.reply_to_graph_id)}/createReply`,
        body: { message: { toRecipients: recips(p.to), ccRecipients: recips(p.cc), bccRecipients: recips(p.bcc),
                           body: { contentType: 'HTML', content: p.body_html } } },
      };
    case 'new_mail':
    case 'notify_internal':
      return {
        method: 'POST',
        url: `${mailbox(item)}/messages`,
        body: { subject: p.subject, body: { contentType: 'HTML', content: p.body_html },
                toRecipients: recips(p.to), ccRecipients: recips(p.cc), bccRecipients: recips(p.bcc) },
      };
    case 'create_hold':
      return {
        method: 'POST',
        url: `${calendarOwner(item)}/events`,
        body: {
          subject: p.subject || 'Hold (Sarah)',
          start: { dateTime: utcLocal(p.start), timeZone: 'UTC' },
          end: { dateTime: utcLocal(p.end), timeZone: 'UTC' },
          showAs: 'tentative', sensitivity: 'private', isReminderOn: false,
          categories: [HOLD_CATEGORY],
          body: { contentType: 'text', content: 'Held by Sarah while a client picks a time. Released automatically.' },
          transactionId: `sarah-hold-${item.offer_id || item.id}`,
        },
      };
    case 'delete_hold':
      return { method: 'DELETE', url: `${calendarOwner(item)}/events/${enc(p.event_id)}`, body: null };
    case 'create_booking': {
      const body = {
        subject: p.subject,
        body: { contentType: 'HTML', content: p.body_html || '' },
        start: p.start,
        end: p.end,
        attendees: (p.attendees || []).map((a) => ({ emailAddress: { address: a.address, name: a.name || a.address }, type: 'required' })),
        allowNewTimeProposals: true,
        responseRequested: true,
        transactionId: `sarah-booking-${item.offer_id || item.id}`,
      };
      if (p.location_type === 'teams') {
        body.isOnlineMeeting = true;
        body.onlineMeetingProvider = 'teamsForBusiness';
      } else if (p.location_type === 'in_person') {
        body.location = { displayName: p.location_text || 'In person' };
      } else if (p.location_type === 'phone') {
        body.location = { displayName: p.location_text ? `Phone: ${p.location_text}` : 'Phone call' };
      }
      return { method: 'POST', url: `${calendarOwner(item)}/events`, body };
    }
    default:
      throw new Error(`unknown outbox kind ${item.kind}`);
  }
}

// n8n HTTP Request with fullResponse + neverError gives {statusCode, body};
// a network failure (with "continue on error") gives {error}.
function classify(resp) {
  if (!resp || resp.error || resp.statusCode === undefined) {
    return { ok: false, retry: true, error: `network: ${JSON.stringify((resp && resp.error) || resp).slice(0, 400)}` };
  }
  const s = Number(resp.statusCode);
  if (s >= 200 && s < 300) return { ok: true, status: s, body: resp.body || {} };
  const msg = resp.body && resp.body.error ? `${resp.body.error.code}: ${resp.body.error.message}` : JSON.stringify(resp.body || '').slice(0, 400);
  return { ok: false, status: s, retry: s === 429 || s >= 500, error: `HTTP ${s} ${msg}` };
}

/**
 * Interpret the first response. Returns either a final report
 * ({ report: {...} }) or a second request to make ({ next: {...}, draft_graph_id, conversation_id }).
 */
function afterFirst(item, resp) {
  const base = { id: item.id };
  if (item.step === 'await_approval') return { report: { ...base, outcome: 'awaiting_approval' } };

  const req = firstRequest(item);
  const c = classify(resp);
  if (!c.ok && req.broker && c.status === 409 && resp.body && resp.body.error && resp.body.error.code === 'NeedsReconnect') {
    // The employee's token is dead. Retrying won't help; the thread goes back to them.
    return { report: { ...base, outcome: 'failed', error_code: 'needs_reconnect', error: 'NeedsReconnect: the employee must reconnect their calendar' } };
  }
  if (!c.ok) {
    if (item.kind === 'delete_hold' && c.status === 404) return { report: { ...base, outcome: 'done', result: { already_gone: true } } };
    if (req.sends && c.status === 404) return { report: { ...base, outcome: 'failed', error: 'draft no longer exists (deleted from Drafts?)' } };
    return { report: { ...base, outcome: c.retry ? 'retry' : 'failed', error: c.error } };
  }

  if (req.sends) {
    return { report: { ...base, outcome: 'done', draft_graph_id: item.draft_graph_id,
                       result: { conversation_id: (item.result && item.result.conversation_id) || null } } };
  }

  const b = c.body || {};
  switch (item.kind) {
    case 'reply':
    case 'new_mail':
    case 'notify_internal': {
      if (!b.id) return { report: { ...base, outcome: 'retry', error: 'draft created without id' } };
      if (item.step === 'draft_only') {
        return { report: { ...base, outcome: 'awaiting_approval', draft_graph_id: b.id, result: { conversation_id: b.conversationId } } };
      }
      return {
        next: { method: 'POST', url: `${mailbox(item)}/messages/${enc(b.id)}/send`, body: null },
        draft_graph_id: b.id,
        conversation_id: b.conversationId,
      };
    }
    case 'create_hold':
    case 'create_booking':
      if (!b.id) return { report: { ...base, outcome: 'retry', error: 'event created without id' } };
      return { report: { ...base, outcome: 'done', result: { event_id: b.id, web_link: b.webLink || null,
                                                             join_url: (b.onlineMeeting && b.onlineMeeting.joinUrl) || null } } };
    case 'delete_hold':
      return { report: { ...base, outcome: 'done' } };
    default:
      return { report: { ...base, outcome: 'failed', error: `unknown kind ${item.kind}` } };
  }
}

/** Interpret the send call that follows a draft. */
function afterSecond(item, first, resp) {
  const c = classify(resp);
  const base = { id: item.id, draft_graph_id: first.draft_graph_id };
  if (c.ok) return { ...base, outcome: 'done', result: { conversation_id: first.conversation_id } };
  return { ...base, outcome: c.retry ? 'retry' : 'failed', error: c.error, result: { conversation_id: first.conversation_id } };
}

module.exports = { firstRequest, afterFirst, afterSecond, classify, recips };

}, {"./luxon":"luxon.js","./slots":"slots.js"}],
  "luxon.js": [function (module, exports, require) {
'use strict';
// Luxon shim. Inside an n8n Code node, Luxon's DateTime is a global. In unit
// tests (plain Node) it comes from the luxon package. The build never bundles
// 'luxon' itself; only relative requires are inlined.
/* global DateTime, Interval, Duration */
if (typeof DateTime !== 'undefined') {
  module.exports = { DateTime, Interval: typeof Interval !== 'undefined' ? Interval : undefined,
                     Duration: typeof Duration !== 'undefined' ? Duration : undefined };
} else {
  module.exports = require('luxon');
}

}, {}],
  "slots.js": [function (module, exports, require) {
'use strict';
// Slot selection. Pure code, no model involvement: which times are free, which
// are "clean" (not back-to-back), and which three go in front of the client.
//
// Hard rules (a slot is never offered if it breaks one):
//   * no overlap with a busy/tentative/OOF event or another thread's live offer
//   * at least hard_gap_min on each side (in_person_buffer_min for in-person)
//   * inside working hours, at least min_notice_hours from now
//   * fewer than max_meetings_per_day meetings that day
// Soft preferences (score penalties; see docs/01-architecture.md):
//   gap before < preferred_gap_min −40 · gap after < preferred −40 ·
//   creates a run of 3+ meetings −30 · day already has 4+ meetings −15 ·
//   outside preferred hours −10
const { DateTime } = require('./luxon');
const { lower } = require('./util');

const HOLD_CATEGORY = 'Sarah hold';
const DAY_KEYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const MIN = 60 * 1000;

function parseGraphTime(t) {
  if (!t || !t.dateTime) return NaN;
  // Graph returns 7 fractional digits; trim to milliseconds for Luxon.
  const iso = String(t.dateTime).replace(/(\.\d{3})\d+/, '$1');
  const zone = !t.timeZone || /^(utc|coordinated universal time)$/i.test(t.timeZone) ? 'utc' : t.timeZone;
  return DateTime.fromISO(iso, { zone }).toMillis();
}

// Graph calendarView events → busy intervals (ms). Skips free, workingElsewhere,
// cancelled, declined, Sarah's own holds (the DB's offers are authoritative for
// those), and all-day events unless they are busy or out-of-office.
function busyFromEvents(events) {
  return (events || [])
    .filter((ev) => {
      if (ev.isCancelled) return false;
      const show = lower(ev.showAs || 'busy');
      if (show === 'free' || show === 'workingelsewhere') return false;
      if ((ev.categories || []).some((c) => lower(c) === lower(HOLD_CATEGORY))) return false;
      if (ev.responseStatus && lower(ev.responseStatus.response) === 'declined') return false;
      if (ev.isAllDay && !(show === 'busy' || show === 'oof')) return false;
      return true;
    })
    .map((ev) => ({
      start: parseGraphTime(ev.start),
      end: parseGraphTime(ev.end),
      allDay: !!ev.isAllDay,
      kind: 'event',
      id: ev.id,
    }))
    .filter((b) => Number.isFinite(b.start) && Number.isFinite(b.end) && b.end > b.start);
}

function offersToBlocks(offers) {
  return (offers || []).map((o) => ({
    start: DateTime.fromISO(o.start, { setZone: true }).toMillis(),
    end: DateTime.fromISO(o.end, { setZone: true }).toMillis(),
    allDay: false,
    kind: 'offer',
    id: o.id,
  }));
}

function parseHm(s) {
  const [h, m] = String(s).split(':').map(Number);
  return { hour: h, minute: m || 0 };
}

function timeOfDayOk(start, tod) {
  if (!tod || tod === 'any') return true;
  if (tod === 'morning') return start.hour < 12;
  if (tod === 'afternoon') return start.hour >= 12;
  return true;
}

// Context shared by candidate generation and single-slot checks.
function prepare(p) {
  const emp = p.employee;
  const zone = emp.timezone;
  const durMs = p.durationMin * MIN;
  const inPerson = p.locationType === 'in_person';
  const hardGapMs = Math.max(emp.hard_gap_min, inPerson ? emp.in_person_buffer_min || 0 : 0) * MIN;
  const prefGapMs = Math.max(emp.preferred_gap_min, hardGapMs / MIN) * MIN;
  const blocks = [...(p.busy || []), ...offersToBlocks(p.otherOffers)].sort((a, b) => a.start - b.start);
  const timed = blocks.filter((b) => !b.allDay);
  const eventsByDay = {};
  for (const b of timed) {
    if (b.kind !== 'event') continue;
    const k = DateTime.fromMillis(b.start, { zone }).toISODate();
    eventsByDay[k] = (eventsByDay[k] || 0) + 1;
  }
  const now = DateTime.fromISO(p.now, { setZone: true }).setZone(zone);
  return { emp, zone, durMs, hardGapMs, prefGapMs, blocks, timed, eventsByDay, now };
}

// Score one concrete slot. Returns null if it breaks a hard rule.
function evaluate(P, startDT, opts = {}) {
  const s = startDT.toMillis();
  const e = s + P.durMs;
  const gap = opts.ignoreGaps ? 0 : P.hardGapMs;

  for (const b of P.blocks) {
    if (b.start < e + gap && b.end > s - gap) return null;
  }

  const dayKey = startDT.toISODate();
  const dayCount = P.eventsByDay[dayKey] || 0;
  if (!opts.ignoreDayCap && dayCount >= P.emp.max_meetings_per_day) return null;

  let prevEnd = -Infinity;
  let nextStart = Infinity;
  for (const b of P.timed) {
    if (b.end <= s && b.end > prevEnd) prevEnd = b.end;
    if (b.start >= e && b.start < nextStart) nextStart = b.start;
  }
  const gapBefore = s - prevEnd;
  const gapAfter = nextStart - e;

  let score = 100;
  const flags = [];
  if (gapBefore < P.prefGapMs) { score -= 40; flags.push('back_to_back_before'); }
  if (gapAfter < P.prefGapMs) { score -= 40; flags.push('back_to_back_after'); }

  // Run length: walk the chain of meetings separated by less than the preferred gap.
  const chain = [...P.timed, { start: s, end: e, self: true }].sort((a, b) => a.start - b.start);
  const idx = chain.findIndex((x) => x.self);
  let len = 1;
  for (let i = idx; i > 0 && chain[i].start - chain[i - 1].end < P.prefGapMs; i--) len++;
  for (let i = idx; i < chain.length - 1 && chain[i + 1].start - chain[i].end < P.prefGapMs; i++) len++;
  if (len >= 3) { score -= 30; flags.push('long_run'); }

  if (dayCount >= 4) { score -= 15; flags.push('busy_day'); }

  const ps = parseHm(P.emp.preferred_start);
  const pe = parseHm(P.emp.preferred_end);
  const minutes = startDT.hour * 60 + startDT.minute;
  const endMinutes = minutes + P.durMs / MIN;
  if (minutes < ps.hour * 60 + ps.minute || endMinutes > pe.hour * 60 + pe.minute) {
    score -= 10; flags.push('outside_preferred_hours');
  }

  return {
    start: DateTime.fromMillis(s, { zone: 'utc' }).toISO({ suppressMilliseconds: true }),
    end: DateTime.fromMillis(e, { zone: 'utc' }).toISO({ suppressMilliseconds: true }),
    startMs: s,
    endMs: e,
    day: dayKey,
    score,
    flags,
    clean: !flags.includes('back_to_back_before') && !flags.includes('back_to_back_after'),
  };
}

function workingWindow(emp, day) {
  const hours = emp.working_hours ? emp.working_hours[DAY_KEYS[day.weekday - 1]] : null;
  if (!hours || !hours[0] || !hours[1]) return null;
  const ws = parseHm(hours[0]);
  const we = parseHm(hours[1]);
  return {
    start: day.set({ hour: ws.hour, minute: ws.minute, second: 0, millisecond: 0 }),
    end: day.set({ hour: we.hour, minute: we.minute, second: 0, millisecond: 0 }),
  };
}

// The days candidates() walks. It starts at the latest of today, windowStart,
// and a requested earliest_date (never inside min notice), and runs windowDays
// (+ widenDays) from there. The calendar read covers the same days
// (decide.calendarRequest). beyondHorizon: the start is more than
// maxHorizonDays out (today is day 0), so nothing is offered.
function searchWindow(p) {
  const emp = p.employee;
  const zone = emp.timezone;
  const now = DateTime.fromISO(p.now, { setZone: true }).setZone(zone);
  const c = p.constraints || {};
  let start = now;
  if (p.windowStart) {
    const ws = DateTime.fromISO(p.windowStart, { setZone: true }).setZone(zone);
    if (ws > start) start = ws;
  }
  if (c.earliest_date) {
    const notice = now.plus({ hours: emp.min_notice_hours });
    const ed = DateTime.fromISO(c.earliest_date, { zone });
    const s = ed > notice ? ed : notice;
    if (s > start) start = s;
  }
  const first = start.startOf('day');
  const passDays = p.windowDays || emp.search_window_days;
  const totalDays = passDays + (p.widenDays || 0);
  const horizonEnd = p.maxHorizonDays ? now.startOf('day').plus({ days: p.maxHorizonDays }) : null;
  return { first, passDays, totalDays, end: first.plus({ days: totalDays }),
           beyondHorizon: !!horizonEnd && first >= horizonEnd };
}

// All hard-legal candidates in the window (+ widen days), with a pass marker.
function candidates(p) {
  const P = prepare(p);
  const c = p.constraints || {};
  const step = (p.stepMin || 30) * MIN;
  const earliest = P.now.plus({ hours: P.emp.min_notice_hours });
  const W = searchWindow(p);
  if (W.beyondHorizon) return [];
  const { first, totalDays } = W;
  const exclude = new Set((p.excludeStarts || []).map((x) => DateTime.fromISO(x, { setZone: true }).toMillis()));
  const days = (c.days_of_week || []).map(lower).filter((d) => DAY_KEYS.includes(d));

  const out = [];
  for (let i = 0; i < totalDays; i++) {
    const day = first.plus({ days: i });
    const iso = day.toISODate();
    if (c.earliest_date && iso < c.earliest_date) continue;
    if (c.latest_date && iso > c.latest_date) break;
    if (days.length && !days.includes(DAY_KEYS[day.weekday - 1])) continue;
    const w = workingWindow(P.emp, day);
    if (!w) continue;
    for (let t = w.start; t.toMillis() + P.durMs <= w.end.toMillis(); t = t.plus({ milliseconds: step })) {
      if (t < earliest) continue;
      if (!timeOfDayOk(t, c.time_of_day)) continue;
      if (exclude.has(t.toMillis())) continue;
      const cand = evaluate(P, t);
      if (cand) {
        cand.pass = i < W.passDays ? 1 : 2;
        out.push(cand);
      }
    }
  }
  return out;
}

const byScoreThenTime = (a, b) => b.score - a.score || a.startMs - b.startMs;
const overlaps = (a, b) => a.startMs < b.endMs && b.startMs < a.endMs;

const minuteOfDay = (c) => { const d = new Date(c.startMs); return d.getUTCHours() * 60 + d.getUTCMinutes(); };

// One slot per day first (spread across days), then fill from the rest.
// Within a day, among the top-scoring candidates, prefer a time of day far
// from the times already chosen, so the client sees a morning/afternoon mix.
function pickSpread(list, n) {
  const byDay = {};
  for (const c of list) (byDay[c.day] = byDay[c.day] || []).push(c);
  const dayBest = Object.values(byDay).map((cs) => {
    const top = Math.max(...cs.map((c) => c.score));
    return { day: cs[0].day, score: top, firstMs: Math.min(...cs.filter((c) => c.score === top).map((c) => c.startMs)),
             options: cs.filter((c) => c.score === top) };
  }).sort((a, b) => b.score - a.score || a.firstMs - b.firstMs).slice(0, n);
  const chosen = [];
  for (const d of dayBest.sort((a, b) => a.firstMs - b.firstMs)) {
    let pick = d.options.sort((a, b) => a.startMs - b.startMs)[0];
    if (chosen.length) {
      const dist = (c) => Math.min(...chosen.map((x) => Math.abs(minuteOfDay(x) - minuteOfDay(c))));
      pick = [...d.options].sort((a, b) => dist(b) - dist(a) || a.startMs - b.startMs)[0];
    }
    chosen.push(pick);
  }
  for (const c of [...list].sort(byScoreThenTime)) {
    if (chosen.length >= n) break;
    if (!chosen.includes(c) && !chosen.some((x) => overlaps(x, c))) chosen.push(c);
  }
  return chosen;
}

const distinctDays = (list) => new Set(list.map((c) => c.day)).size;

/**
 * Pick the slots to offer. Fallback order when clean slots are scarce:
 *   1. clean slots in the normal window, one per day
 *   2. widen the window by widenDays and try again
 *   3. offer fewer (but at least 2) clean slots
 *   4. only then include back-to-back slots, ranked last
 * Returns { slots: [...with option_no], note, window }. note 'beyond_horizon':
 * the requested window starts past maxHorizonDays, so nothing is offered.
 */
function pickSlots(p) {
  const n = p.count || p.employee.offers_per_round || 3;
  const window = searchWindow(p);
  if (window.beyondHorizon) return { slots: [], note: 'beyond_horizon', considered: 0, window };
  const all = candidates(p);
  const pass1 = all.filter((c) => c.pass === 1);
  const clean1 = pass1.filter((c) => c.clean);
  const cleanAll = all.filter((c) => c.clean);

  let chosen;
  let note;
  if (distinctDays(clean1) >= n) {
    chosen = pickSpread(clean1, n); note = 'clean';
  } else if (distinctDays(cleanAll) >= n) {
    chosen = pickSpread(cleanAll, n); note = 'clean_widened';
  } else if (cleanAll.length >= 2) {
    chosen = pickSpread(cleanAll, n); note = 'fewer_clean';
  } else {
    const clean = pickSpread(cleanAll, n);
    const rest = all.filter((c) => !c.clean && !clean.some((x) => overlaps(x, c)));
    chosen = [...clean, ...pickSpread(rest, n - clean.length)];
    note = chosen.length ? 'includes_back_to_back' : 'none';
  }

  // Clean slots first (chronological), back-to-back ones last.
  chosen.sort((a, b) => (a.clean === b.clean ? a.startMs - b.startMs : a.clean ? -1 : 1));
  const slots = chosen.map((c, i) => ({
    option_no: i + 1, start: c.start, end: c.end, score: c.score, flags: c.flags,
  }));
  return { slots, note, considered: all.length, window };
}

/**
 * Check one specific slot (a client's counter-proposal, or re-checking an
 * accepted slot before asking Vic / before booking).
 *   mode 'propose' — all hard rules incl. working hours + notice
 *   mode 'booking' — Vic already said yes: only a real overlap blocks it
 */
function checkSlot(p, startIso, endIso, mode = 'propose') {
  const P = prepare(p);
  const start = DateTime.fromISO(startIso, { setZone: true }).setZone(P.zone);
  const end = DateTime.fromISO(endIso, { setZone: true }).setZone(P.zone);
  P.durMs = end.toMillis() - start.toMillis();

  if (mode === 'propose') {
